import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read = path => readFileSync(new URL(path, import.meta.url), 'utf8');
const page = read('../index.php');
const script = read('../script.js');
const dns = read('../native/android/DAGServerDns.java');
const media = read('../native/android/DAGAudioEngine.java');
assert.doesNotMatch(page, /id="studio-header-offline"/, 'No manual Offline header item');
assert.doesNotMatch(page, /data-mix="charts"/, 'No Charts collection item');
assert.match(page, /id="cache-dashboard-modal"/, 'Cached audio stays manageable');
assert.match(script, /startOfflineListening\(\{auto:true,autoplay:true\}\)/);
assert.match(script, /getDeviceCachedAudio\(track\)/);
assert.match(script, /await getDeviceCachedAudio\(track\)/);
assert.match(script, /buffered\.end\(i\) >= Math\.min\(duration - 1\.5/);
assert.match(dns, /Dns\.SYSTEM\.lookup\(HOST\)/);
assert.match(dns, /resolver\.execute/);
assert.match(dns, /candidates\.add\(trusted\)/);
assert.match(media, /setBufferDurationsMs\(18000, 150000, 900, 5000\)/);
const nativeCache = read('../native/native-bridge.js');
const audioNative = read('../native/android/DAGCarModePlugin.java');
const otaNative = read('../native/android/DAGUpdaterDns.java');
const androidBuild = read('./workflows/build-android.yml');
assert.match(nativeCache, /DAGCarMode\.downloadOwnAudio/);
assert.match(audioNative, /new DAGServerDns\(\)/);
assert.match(audioNative, /downloadOwnAudio\(PluginCall call\)/);
assert.match(otaNative, /previous\.newBuilder\(\)\.dns\(new DAGServerDns\(\)\)/);
assert.match(audioNative, /DAGUpdaterDns\.install\(\)/);
assert.match(androidBuild, /cp native\/android\/DAGUpdaterDns\.java/);
console.log('CC3_OFFLINE_UI_STREAM_BUFFER_TLS_DNS_AND_NATIVE_OTA_OK');
